std::vector<SyncPeerChunkAvailability> sorted_peer_availabilities(std::vector<SyncPeerChunkAvailability> peers) {
    std::sort(peers.begin(), peers.end(), [](const SyncPeerChunkAvailability& left,
                                             const SyncPeerChunkAvailability& right) {
        if (left.peer_id != right.peer_id) return left.peer_id < right.peer_id;
        return left.peer_session_id < right.peer_session_id;
    });
    return peers;
}

std::string digest_peer_chunk_availabilities(const std::vector<SyncPeerChunkAvailability>& peers) {
    std::string material;
    std::uint64_t index = 0;
    for (const auto& peer : peers) {
        material += length_prefixed_security_tuple("anonsync-sync-peer-chunk-availability-list-v1", {
            {"peer_index", u64_string(index)},
            {"peer_id", peer.peer_id},
            {"peer_session_id", peer.peer_session_id},
            {"max_chunks", u64_string(peer.max_chunks)},
            {"max_bytes", u64_string(peer.max_bytes)},
            {"available_chunks_digest", digest_chunks(peer.available_chunks)}
        });
        ++index;
    }
    return sha256_hex(material);
}

