void inspect_resume_action_receipts_or_throw(sqlite3* db,
                                             const std::string& session_id,
                                             const NormalizedSyncPath& path,
                                             const std::string& remote_entry_digest,
                                             const fs::path& staging_root,
                                             const fs::path& receipt_dir,
                                             SyncSessionCheckpointResumeActionFilePlan& file) {
    SyncSqliteStmt stmt = sqlite_prepare_or_throw(db,
        "SELECT mc.chunk_offset, mc.chunk_length, mc.chunk_sha256, "
        "COALESCE(cr.receipt_idempotency_key,''), COALESCE(cr.receipt_state,''), cr.path IS NOT NULL "
        "FROM sync_session_manifest_chunks mc "
        "LEFT JOIN sync_session_chunk_receipts cr ON cr.session_id=mc.session_id AND cr.path=mc.path "
        "AND cr.chunk_offset=mc.chunk_offset AND cr.chunk_length=mc.chunk_length AND cr.chunk_sha256=mc.chunk_sha256 "
        "WHERE mc.session_id=? AND mc.role='source' AND mc.path=? ORDER BY mc.chunk_offset;",
        "sync session checkpoint resume action receipt scan");
    sqlite_bind_text_or_throw(stmt.stmt, 1, session_id, "resume action receipt session");
    sqlite_bind_text_or_throw(stmt.stmt, 2, path.value, "resume action receipt path");

    std::vector<fs::path> expected_receipt_paths;
    while (true) {
        const int rc = sqlite3_step(stmt.stmt);
        if (rc == SQLITE_DONE) break;
        if (rc != SQLITE_ROW) throw std::runtime_error("sync session checkpoint resume action receipt query failed");
        const SyncChunkRange chunk{
            sqlite_column_u64_or_throw(stmt.stmt, 0, "resume action receipt offset"),
            sqlite_column_u64_or_throw(stmt.stmt, 1, "resume action receipt length"),
            sqlite_column_text_or_throw(stmt.stmt, 2, "resume action receipt sha")
        };
        if (!is_lowercase_sha256_hex(chunk.sha256)) {
            throw std::runtime_error("sync session checkpoint resume action manifest chunk carries invalid hash");
        }
        ++file.chunks_total;
        const bool row_present = sqlite_column_bool_or_throw(stmt.stmt, 5, "resume action receipt row present");
        std::string receipt_key;
        std::string receipt_state;
        if (row_present) {
            receipt_key = sqlite_column_text_or_throw(stmt.stmt, 3, "resume action receipt key");
            receipt_state = sqlite_column_text_or_throw(stmt.stmt, 4, "resume action receipt state");
            if (!receipt_key.starts_with("sync-chunk-receipt:v1:")) {
                throw std::runtime_error("sync session checkpoint resume action receipt row carries invalid idempotency key");
            }
            if (receipt_state == "accepted") {
                ++file.accepted_receipt_rows;
            } else if (receipt_state == "committed-cleaned") {
                ++file.committed_cleaned_receipt_rows;
            } else {
                throw std::runtime_error("sync session checkpoint resume action receipt row carries invalid state");
            }
            ++file.receipt_rows_recorded;
        }

        const NormalizedSyncPath receipt_relative{
            chunk_receipt_relative_path_for_digest_or_throw(path,
                                                            remote_entry_digest,
                                                            chunk,
                                                            "sync session checkpoint resume action receipt path")
        };
        const fs::path receipt_path = fs::path(resolve_normalized_relative_under_root_or_throw(staging_root,
                                                                                              receipt_relative,
                                                                                              "sync session checkpoint resume action receipt path"));
        expected_receipt_paths.push_back(receipt_path);
        require_no_symlink_ancestors_under_root_or_throw(staging_root,
                                                         receipt_path,
                                                         "sync session checkpoint resume action receipt path");
        std::error_code receipt_ec;
        const fs::file_status receipt_status = fs::symlink_status(receipt_path, receipt_ec);
        if (receipt_ec && receipt_ec != std::errc::no_such_file_or_directory) {
            throw std::runtime_error("sync session checkpoint resume action could not inspect receipt: " + receipt_ec.message());
        }
        if (receipt_ec || !fs::exists(receipt_status)) {
            ++file.missing_receipts;
            file.chunks_to_request.push_back(chunk);
            continue;
        }
        if (fs::is_symlink(receipt_status) || !fs::is_regular_file(receipt_status)) {
            ++file.receipt_kind_mismatches;
            file.chunks_to_request.push_back(chunk);
            continue;
        }
        ++file.receipt_files_present;
        if (!row_present) {
            ++file.missing_receipts;
            file.chunks_to_request.push_back(chunk);
            continue;
        }
        const std::string receipt_material = read_file(receipt_path.string());
        const std::string actual_receipt_key = "sync-chunk-receipt:v1:" + sha256_hex(receipt_material);
        if (actual_receipt_key != receipt_key) {
            ++file.receipt_content_mismatches;
            file.chunks_to_request.push_back(chunk);
            continue;
        }
        ++file.receipt_files_verified;
    }

    file.receipt_rows_match_manifest = (file.receipt_rows_recorded == file.chunks_total);
    file.all_receipts_verified = (file.receipt_rows_match_manifest &&
                                  file.receipt_files_verified == file.chunks_total &&
                                  file.missing_receipts == 0 &&
                                  file.receipt_content_mismatches == 0 &&
                                  file.receipt_kind_mismatches == 0);

    std::error_code receipt_dir_ec;
    const fs::file_status receipt_dir_status = fs::symlink_status(receipt_dir, receipt_dir_ec);
    if (receipt_dir_ec && receipt_dir_ec != std::errc::no_such_file_or_directory) {
        throw std::runtime_error("sync session checkpoint resume action could not inspect receipt directory: " + receipt_dir_ec.message());
    }
    if (!receipt_dir_ec && fs::exists(receipt_dir_status)) {
        file.receipt_directory_present = true;
        if (fs::is_symlink(receipt_dir_status) || !fs::is_directory(receipt_dir_status)) {
            ++file.receipt_kind_mismatches;
            return;
        }
        require_no_symlink_ancestors_under_root_or_throw(staging_root,
                                                         receipt_dir,
                                                         "sync session checkpoint resume action receipt directory");
        std::error_code iter_ec;
        for (fs::directory_iterator it(receipt_dir, iter_ec), end; it != end; it.increment(iter_ec)) {
            if (iter_ec) throw std::runtime_error("sync session checkpoint resume action could not iterate receipt directory: " + iter_ec.message());
            const fs::path child = it->path();
            if (!path_vector_contains_lexically(expected_receipt_paths, child)) {
                ++file.unexpected_receipt_artifacts;
            }
        }
    }
}


std::vector<SyncChunkRange> select_checkpoint_resume_transfer_chunks_or_throw(const std::vector<SyncChunkRange>& missing_chunks,
                                                                              std::uint64_t max_chunks,
                                                                              std::uint64_t max_bytes,
                                                                              std::uint64_t& selected_bytes_out) {
    selected_bytes_out = 0;
    std::vector<SyncChunkRange> selected;
    for (const auto& chunk : missing_chunks) {
        if (max_chunks != 0 && selected.size() >= static_cast<size_t>(max_chunks)) break;
        if (max_bytes != 0) {
            if (chunk.length > max_bytes && selected.empty()) {
                throw std::runtime_error("sync session checkpoint resume transfer byte budget is smaller than the first missing chunk");
            }
            if (chunk.length > std::numeric_limits<std::uint64_t>::max() - selected_bytes_out) {
                throw std::runtime_error("sync session checkpoint resume transfer selected byte count overflow");
            }
            if (selected_bytes_out + chunk.length > max_bytes) break;
        } else if (chunk.length > std::numeric_limits<std::uint64_t>::max() - selected_bytes_out) {
            throw std::runtime_error("sync session checkpoint resume transfer selected byte count overflow");
        }
        selected.push_back(chunk);
        selected_bytes_out += chunk.length;
    }
    if (selected.empty() && !missing_chunks.empty()) {
        throw std::runtime_error("sync session checkpoint resume transfer selector produced no work for a non-empty missing chunk set");
    }
    return selected;
}

std::string checkpoint_resume_transfer_request_idempotency_key_or_throw(const std::string& remote_entry_digest,
                                                                        const std::string& remote_version_digest,
                                                                        const std::string& apply_intent_key,
                                                                        const NormalizedSyncPath& path,
                                                                        const std::string& staging_path,
                                                                        std::uint64_t max_chunks,
                                                                        std::uint64_t max_bytes,
                                                                        std::uint64_t total_missing_chunks,
                                                                        const std::vector<SyncChunkRange>& selected_chunks) {
    if (!is_lowercase_sha256_hex(remote_entry_digest) || !is_lowercase_sha256_hex(remote_version_digest)) {
        throw std::runtime_error("sync session checkpoint resume transfer request key requires digest evidence");
    }
    if (!apply_intent_key.starts_with("sync-local-apply:v1:")) {
        throw std::runtime_error("sync session checkpoint resume transfer request key requires apply intent evidence");
    }
    const std::string material = length_prefixed_security_tuple("anonsync-sync-checkpoint-resume-transfer-request-v1", {
        {"remote_entry_digest", remote_entry_digest},
        {"remote_version_digest", remote_version_digest},
        {"apply_intent_key", apply_intent_key},
        {"path", path.value},
        {"staging_path", staging_path},
        {"max_chunks_per_request", u64_string(max_chunks)},
        {"max_bytes_per_request", u64_string(max_bytes)},
        {"total_missing_chunks", u64_string(total_missing_chunks)},
        {"selected_chunks_digest", digest_chunks(selected_chunks)}
    });
    return "sync-resume-transfer-request:v1:" + sha256_hex(material);
}

